css:
.opensim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #e7ecf3;
    background: linear-gradient(160deg, #0d1320 0%, #131c2e 60%, #101a2b 100%);
    border-radius: 18px;
}

.opensim-container * {
    box-sizing: border-box;
}

.opensim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #11203a 0%, #1b3358 55%, #244a7a 100%);
    color: #f1f5fb;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(0, 0, 0, 0.45);
    border: 1px solid #2b4a78;
}

.opensim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffffff;
}

.opensim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffce6b;
    background: rgba(255, 206, 107, 0.12);
    border: 1px solid rgba(255, 206, 107, 0.3);
    padding: 5px 14px;
    border-radius: 999px;
}

.opensim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #c8d6ea;
}

.opensim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #aebfd6;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.opensim-period-counter #currentDay,
.opensim-period-counter #maxPeriods {
    font-weight: 800;
    color: #ffce6b;
}

.opensim-round-name {
    background: rgba(255, 206, 107, 0.14);
    color: #ffce6b;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
    border: 1px solid rgba(255, 206, 107, 0.3);
}

.opensim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #ff9a8a;
    background: rgba(255, 90, 70, 0.14);
    padding: 4px 12px;
    border-radius: 999px;
    border: 1px solid rgba(255, 90, 70, 0.3);
}

.opensim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.opensim-status-card {
    background: #16213a;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #28395c;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
    border-top: 4px solid #3c6db0;
}

.opensim-card-value { border-top-color: #ffce6b; }
.opensim-card-ip { border-top-color: #45c4a8; }
.opensim-card-ttm { border-top-color: #5aa0f0; }
.opensim-card-budget { border-top-color: #b18cf0; }

.opensim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8ea2c2;
}

.opensim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #f1f5fb;
}

.opensim-card-value .opensim-value { color: #ffce6b; }
.opensim-card-ip .opensim-value { color: #45c4a8; }
.opensim-card-ttm .opensim-value { color: #5aa0f0; }
.opensim-card-budget .opensim-value { color: #b18cf0; }

.opensim-sublabel {
    font-size: 0.76rem;
    color: #7f93b4;
    line-height: 1.35;
}

.opensim-value-win .opensim-value { color: #5fe0a8; }
.opensim-value-low .opensim-value { color: #ff7a6b; }

.opensim-ip-weak { border-top-color: #ff7a6b; }
.opensim-ip-weak .opensim-value { color: #ff7a6b; }

.opensim-ttm-late { border-top-color: #ff7a6b; }
.opensim-ttm-late .opensim-value { color: #ff7a6b; }
.opensim-ttm-window .opensim-value { color: #5fe0a8; }

.opensim-budget-over { border-top-color: #ff7a6b; }
.opensim-budget-over .opensim-value { color: #ff7a6b; }

.opensim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f1a30;
    color: #dbe6f7;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border: 1px solid #28395c;
}

.opensim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
    color: #b18cf0;
}

.opensim-budget-bar.opensim-bar-over #budgetDisplay {
    color: #ff7a6b;
}

.opensim-briefing {
    display: flex;
    gap: 14px;
    background: #16213a;
    border-left: 5px solid #ffce6b;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.opensim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.opensim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #ffce6b;
    margin-bottom: 6px;
}

.opensim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #cdd9ec;
}

.opensim-briefing-text strong { color: #5fe0a8; }
.opensim-briefing-text em { color: #ff9a8a; font-style: italic; }

.opensim-controls {
    background: #16213a;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #28395c;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.opensim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #f1f5fb;
    border-bottom: 2px solid #28395c;
    padding-bottom: 8px;
}

.opensim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #c8d6ea;
    margin: 14px 0 6px;
}

.opensim-container select,
.opensim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #34507c;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #0f1a30;
    color: #eaf0fa;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.opensim-container select:focus,
.opensim-container input[type="number"]:focus {
    outline: none;
    border-color: #ffce6b;
    box-shadow: 0 0 0 3px rgba(255, 206, 107, 0.18);
}

.opensim-container select option {
    background-color: #0f1a30;
    color: #eaf0fa;
}

.opensim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #ffce6b;
}

.opensim-range-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #aebfd6;
    margin-top: 4px;
}

.opensim-range-readout span:last-child {
    color: #ffce6b;
    font-weight: 800;
}

.opensim-hint {
    font-size: 0.8rem;
    color: #8395b4;
    margin-top: 4px;
    line-height: 1.4;
}

.opensim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.opensim-container .btn-primary {
    background: linear-gradient(135deg, #d99a26 0%, #ffce6b 100%);
    border: none;
    color: #1a1408;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(217, 154, 38, 0.32);
}

.opensim-container .btn-primary:hover {
    filter: brightness(1.07);
}

.opensim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #34507c;
    color: #aebfd6;
    background: transparent;
}

.opensim-container .btn-outline-secondary:hover {
    background: #1d2c49;
    color: #eaf0fa;
}

.opensim-coach {
    background: #0f1a30;
    color: #dbe6f7;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(0, 0, 0, 0.35);
    border: 1px solid #28395c;
    border-left: 5px solid #45c4a8;
}

.opensim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #45c4a8;
    margin-bottom: 8px;
}

.opensim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.opensim-coach-body strong { color: #ffce6b; }
.opensim-coach-body em { color: #ff9a8a; font-style: italic; }

.opensim-history,
.opensim-chart {
    background: #16213a;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #28395c;
    box-shadow: 0 4px 14px rgba(0, 0, 0, 0.3);
}

.opensim-history h3,
.opensim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #f1f5fb;
}

.opensim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #cdd9ec;
}

.opensim-container table#usfHistoryTable th {
    background: #1d2c49;
    color: #ffce6b;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #34507c;
}

.opensim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #243556;
}

.opensim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #18253f;
}

.opensim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .opensim-container {
        padding: 14px;
    }
    .opensim-header h1 {
        font-size: 1.7rem;
    }
    .opensim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .opensim-value {
        font-size: 2rem;
    }
    .opensim-clock {
        margin-left: 0;
    }
    .opensim-period-counter {
        font-size: 0.88rem;
    }
    .opensim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .opensim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* v1.1.0 completion-message card (appended; dark-on-light, self-contained) */
.opensim-cm { background:#f7fafc; color:#12212f; border-radius:14px; padding:22px 24px; max-width:640px; margin:0 auto; font-family:inherit; box-shadow:0 8px 30px rgba(0,0,0,0.18); }
.opensim-cm-head { text-align:center; border-bottom:1px solid #dde5ee; padding-bottom:14px; margin-bottom:16px; }
.opensim-cm-title { font-size:13px; letter-spacing:.08em; text-transform:uppercase; color:#5a6b7d; font-weight:700; }
.opensim-cm-scorewrap { margin:8px 0 2px; }
.opensim-cm-score { font-size:52px; font-weight:800; color:#0b5cad; line-height:1; }
.opensim-cm-score-max { font-size:20px; color:#8494a5; font-weight:600; }
.opensim-cm-grade { font-size:19px; font-weight:700; color:#12212f; margin-top:4px; }
.opensim-cm-badges { margin-top:12px; display:flex; flex-wrap:wrap; gap:8px; justify-content:center; }
.opensim-cm-badge { font-size:12px; font-weight:700; padding:4px 11px; border-radius:999px; }
.opensim-cm-met { background:#d6e8f8; color:#0b5188; }
.opensim-cm-fail { background:#fce0dc; color:#a4322a; }
.opensim-cm-metrics { display:flex; flex-wrap:wrap; gap:12px; justify-content:center; margin-bottom:16px; }
.opensim-cm-metric { background:#eef3f8; border-radius:10px; padding:12px 16px; min-width:104px; text-align:center; }
.opensim-cm-metric-val { font-size:22px; font-weight:800; color:#12212f; }
.opensim-cm-metric-lbl { font-size:11px; letter-spacing:.05em; text-transform:uppercase; color:#5a6b7d; margin-top:3px; }
.opensim-cm-insights { background:#eef3f8; border-radius:10px; padding:14px 18px; }
.opensim-cm-insights-title { font-size:12px; letter-spacing:.06em; text-transform:uppercase; color:#5a6b7d; font-weight:700; margin-bottom:8px; }
.opensim-cm-insights ul { margin:0; padding-left:18px; }
.opensim-cm-insights li { font-size:14px; line-height:1.5; color:#2a3a4a; margin-bottom:7px; }

