(function() {
    'use strict';

    class OpenInnovationAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Open or Closed?`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brennaro Sistemi S.p.A. — EUR, millions).
            this.START_VALUE = 22;       // blended value capture, 0-100
            this.START_IP = 55;          // IP defensibility / freedom to operate, 0-100
            this.START_TTM = 18;         // in-house build time-to-market, months
            this.RIVAL_TTM = 9;          // German rival 800V launch, months
            this.WINDOW_TTM = 12;        // ship inside the EV window
            this.BUDGET_CAP = 24;        // EUR 24M hard discretionary cap
            this.LICENSE_CASH = 9;       // EUR 9M upfront for the SiC IP
            this.TARGET_VALUE = 70;      // win target on Strategic Value

            // Concept-correct choices (Frattini's open-innovation / technology-leverage logic).
            this.CORRECT = {
                sicClass: `adjacent`, buildClass: `core`, thermalClass: `sourcein`,
                license: `license`, field: `carveout`, exclusivity: `nonexcl_floor`,
                fundBuild: `build`, thermalMode: `equity`, governance: `strong`,
                thread: `recycled`, core: `focused`, register: `full`
            };
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    ip: this.START_IP,
                    ttm: this.START_TTM,
                    budgetUsed: 0,
                    headroom: 0,            // extra spend capacity from ring-fenced licence cash
                    licensed: false,
                    licenseCash: 0,
                    overBudget: false,
                    armedRival: false,      // broad licence handed the architecture to a rival lane
                    valueHistory: [this.START_VALUE],
                    ipHistory: [this.START_IP],
                    ttmHistory: [this.START_TTM],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            // Seeded defaults are deliberately MIDDLING / neutral — never the textbook-correct play.
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    sicClass: `core`,          // closed reflex (wrong) — not the correct "adjacent"
                    buildClass: `adjacent`,    // outsource (wrong)
                    thermalClass: `build`,     // build from scratch (wrong)
                    openness: 50,
                    license: `decline`,        // hoard (wrong) — not the correct "license"
                    field: `broad`,            // arm a rival (wrong)
                    exclusivity: `exclusive`,  // monopoly to licensee (wrong)
                    recycle: 40,
                    fundBuild: `build`,
                    thermalMode: `acquire`,    // bust the cap (wrong) — not the correct "equity"
                    governance: `light`,       // ungoverned (wrong)
                    speed: 50,
                    thread: `piecemeal`,       // no portfolio logic (wrong)
                    core: `everywhere`,        // no defensible focus (wrong)
                    register: `partial`,
                    roi: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const sic = document.getElementById(`sicClassInput`);
                const build = document.getElementById(`buildClassInput`);
                const thermal = document.getElementById(`thermalClassInput`);
                const op = document.getElementById(`opennessInput`);
                if (sic) decisions.sicClass = sic.value;
                if (build) decisions.buildClass = build.value;
                if (thermal) decisions.thermalClass = thermal.value;
                if (op) decisions.openness = parseInt(op.value, 10);
                if (!Number.isFinite(decisions.openness) || decisions.openness < 0 || decisions.openness > 100) {
                    warn(`warn_openness_range`); return false;
                }
            } else if (round === 2) {
                const lic = document.getElementById(`licenseInput`);
                const fld = document.getElementById(`fieldInput`);
                const exc = document.getElementById(`exclusivityInput`);
                const rec = document.getElementById(`recycleInput`);
                if (lic) decisions.license = lic.value;
                if (fld) decisions.field = fld.value;
                if (exc) decisions.exclusivity = exc.value;
                if (rec) decisions.recycle = parseInt(rec.value, 10);
                if (!Number.isFinite(decisions.recycle) || decisions.recycle < 0 || decisions.recycle > 100) {
                    warn(`warn_recycle_range`); return false;
                }
            } else if (round === 3) {
                const fb = document.getElementById(`fundBuildInput`);
                const tm = document.getElementById(`thermalModeInput`);
                const gov = document.getElementById(`governanceInput`);
                const sp = document.getElementById(`speedInput`);
                if (fb) decisions.fundBuild = fb.value;
                if (tm) decisions.thermalMode = tm.value;
                if (gov) decisions.governance = gov.value;
                if (sp) decisions.speed = parseInt(sp.value, 10);
                if (!Number.isFinite(decisions.speed) || decisions.speed < 0 || decisions.speed > 100) {
                    warn(`warn_speed_range`); return false;
                }
            } else if (round === 4) {
                const th = document.getElementById(`threadInput`);
                const co = document.getElementById(`coreInput`);
                const rg = document.getElementById(`registerInput`);
                const roi = document.getElementById(`roiInput`);
                if (th) decisions.thread = th.value;
                if (co) decisions.core = co.value;
                if (rg) decisions.register = rg.value;
                if (roi) decisions.roi = parseInt(roi.value, 10);
                if (!Number.isFinite(decisions.roi) || decisions.roi < 0 || decisions.roi > 100) {
                    warn(`warn_roi_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let valueDelta = 0, ipDelta = 0, ttmDelta = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Map the portfolio: strategic centrality vs internal capability.
                // SiC IP — strong but idle & adjacent: the canonical "leverage an under-exploited asset".
                if (d.sicClass === `adjacent`) { valueDelta += 10; ipDelta += 3; coachKey = `coach_r1_sic_right`; }
                else if (d.sicClass === `core`) { valueDelta -= 6; ipDelta += 2; coachKey = `coach_r1_sic_hoard`; }
                else { valueDelta -= 8; ipDelta -= 6; coachKey = `coach_r1_sic_lapse`; }

                // 800V platform — genuinely core, build it in-house & keep closed.
                if (d.buildClass === `core`) { valueDelta += 8; ipDelta += 6; }
                else if (d.buildClass === `adjacent`) { valueDelta -= 4; ipDelta -= 8; coachKey = `coach_r1_build_outsource`; }
                else { valueDelta -= 8; ttmDelta += 2; coachKey = `coach_r1_build_skip`; }

                // Thermal-management — a capability gap to source in, not to build slowly.
                if (d.thermalClass === `sourcein`) { valueDelta += 8; }
                else if (d.thermalClass === `build`) { valueDelta -= 4; coachKey = `coach_r1_thermal_build`; }
                else { valueDelta -= 8; coachKey = `coach_r1_thermal_ignore`; }

                // Commitment to an open-innovation portfolio vs the closed-innovation reflex.
                if (d.openness >= 60) { valueDelta += 8; }
                else if (d.openness <= 25) { valueDelta -= 8; ipDelta -= 2; coachKey = `coach_r1_closedreflex`; }

                if (d.sicClass === `adjacent` && d.buildClass === `core` && d.thermalClass === `sourcein`) {
                    coachKey = `coach_r1_grid_sharp`;
                    summaryKey = `sum_r1_good`;
                } else {
                    summaryKey = `sum_r1_weak`;
                }
            } else if (round === 2) {
                // Outbound: the SiC license-out decision (Errors 2 & 3).
                if (d.license === `license`) {
                    ds.licensed = true;
                    ds.licenseCash = this.LICENSE_CASH;

                    // Field-of-use design protects the roadmap (robotics is the firm's own backyard).
                    if (d.field === `carveout`) { valueDelta += 8; ipDelta += 8; coachKey = `coach_r2_carveout`; }
                    else if (d.field === `broad`) { valueDelta += 4; ipDelta -= 18; ds.armedRival = true; coachKey = `coach_r2_broad`; }
                    else { valueDelta -= 4; ipDelta += 2; coachKey = `coach_r2_narrow`; }

                    // Exclusivity & royalty structure.
                    if (d.exclusivity === `nonexcl_floor`) { valueDelta += 8; ipDelta += 6; }
                    else if (d.exclusivity === `exclusive`) { valueDelta += 2; ipDelta -= 12; if (!ds.armedRival) coachKey = `coach_r2_exclusive`; }
                    else { valueDelta -= 2; }

                    // Technology leverage: ring-fence the cash to fund inbound innovation.
                    const fenced = Math.round(this.LICENSE_CASH * (d.recycle / 100) * 10) / 10;
                    ds.headroom = Math.round((ds.headroom + fenced) * 10) / 10;
                    if (d.recycle >= 50) { valueDelta += 6; if (d.field === `carveout` && d.exclusivity === `nonexcl_floor`) coachKey = `coach_r2_leverage`; }
                    else if (d.recycle <= 10) { valueDelta -= 2; }

                    summaryKey = (d.field === `carveout` && d.exclusivity !== `exclusive`) ? `sum_r2_good` : `sum_r2_weak`;
                } else {
                    // Hoarding: decline and leave the asset idle and ageing.
                    valueDelta -= 10; ipDelta += 2; coachKey = `coach_r2_decline`;
                    summaryKey = `sum_r2_hoard`;
                }
            } else if (round === 3) {
                // Inbound & in-house: make / buy / ally under the cap (Errors 1 & 4).
                // Build the 800V platform in-house — control & IP, but slow.
                if (d.fundBuild === `build`) { spend += 16; valueDelta += 8; ipDelta += 6; }
                else { valueDelta -= 4; ipDelta -= 4; ttmDelta -= 1; coachKey = `coach_r3_skipbuild`; }

                let hasPartner = false;
                // Thermal-management gap: make / buy / ally.
                if (d.thermalMode === `equity`) { spend += 11; valueDelta += 10; ipDelta += 4; ttmDelta -= 4; hasPartner = true; coachKey = `coach_r3_equity`; }
                else if (d.thermalMode === `alliance`) { spend += 6; valueDelta += 6; ipDelta += 2; ttmDelta -= 5; hasPartner = true; coachKey = `coach_r3_alliance`; }
                else if (d.thermalMode === `acquire`) { spend += 30; valueDelta += 4; ipDelta += 6; ttmDelta -= 3; hasPartner = false; coachKey = `coach_r3_acquire`; }
                else { valueDelta -= 6; ttmDelta += 3; coachKey = `coach_r3_makeit`; }

                // IP-leakage governance on any inbound partnership.
                if (d.governance === `strong`) { spend += 2; ipDelta += 8; if (hasPartner && d.thermalMode === `equity`) coachKey = `coach_r3_governed`; }
                else if (d.governance === `light`) {
                    if (hasPartner) { ipDelta -= 14; valueDelta -= 4; coachKey = `coach_r3_leak`; }
                    else { ipDelta -= 2; }
                } else { // na
                    if (hasPartner) { ipDelta -= 10; coachKey = `coach_r3_ungoverned`; }
                }

                // Speed-to-window is first-order, not secondary.
                if (d.speed >= 60) { ttmDelta -= 3; valueDelta += 4; }
                else if (d.speed <= 25) { ttmDelta += 2; valueDelta -= 4; coachKey = `coach_r3_slow`; }

                summaryKey = (d.thermalMode === `equity` && d.governance === `strong` && d.fundBuild === `build`) ? `sum_r3_good`
                    : (d.thermalMode === `acquire` ? `sum_r3_overbuy` : `sum_r3_weak`);
            } else if (round === 4) {
                // Integrate into one technology-leverage strategy & defend the ROI (Error 5).
                if (d.thread === `recycled`) { valueDelta += 12; ipDelta += 4; coachKey = `coach_r4_recycled`; }
                else if (d.thread === `piecemeal`) { valueDelta -= 8; ipDelta -= 4; coachKey = `coach_r4_piecemeal`; }
                else { valueDelta -= 10; ipDelta += 2; ttmDelta += 3; coachKey = `coach_r4_closed`; }

                if (d.core === `focused`) { ipDelta += 12; valueDelta += 4; if (d.thread === `recycled`) coachKey = `coach_r4_core_sharp`; }
                else if (d.core === `everywhere`) { valueDelta -= 4; ipDelta += 2; }
                else { ipDelta -= 12; valueDelta -= 6; coachKey = `coach_r4_core_nowhere`; }

                if (d.register === `full`) { valueDelta += 8; ipDelta += 6; }
                else if (d.register === `partial`) { valueDelta += 2; }
                else { valueDelta -= 6; ipDelta -= 4; coachKey = `coach_r4_noregister`; }

                // Defend a grounded blended ROI; over-promising erodes board trust.
                if (d.roi >= 40 && d.roi <= 65) { valueDelta += 6; }
                else if (d.roi > 80) { valueDelta -= 6; coachKey = `coach_r4_overpromise`; }
                else if (d.roi < 25) { valueDelta -= 4; }

                summaryKey = (d.thread === `recycled` && d.core === `focused` && d.register === `full`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Damp the POSITIVE reward only so a textbook-perfect run lands high but never
            // pegs the 0-100 meters before the final round — this keeps every later lever
            // (especially the Round-4 portfolio-integration decisions and the arm-a-rival /
            // piecemeal penalties) visible in the final score instead of being eaten by the
            // clamp. Penalties stay full-strength so the wrong play still craters.
            if (valueDelta > 0) valueDelta *= 0.6;
            if (ipDelta > 0) ipDelta *= 0.55;

            // Resource accounting against the hard EUR 24M cap (+ ring-fenced licence headroom).
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;
            const effectiveCap = this.BUDGET_CAP + ds.headroom;
            const over = Math.max(0, ds.budgetUsed - effectiveCap);
            if (over > 0.01) {
                ds.overBudget = true;
                valueDelta -= over * 1.2;       // busting the cap destroys value
                ipDelta -= over * 0.4;
                if (round === 3 && over > 3) coachKey = `coach_r3_bustcap`;
            }

            // Apply deltas with floors/ceilings; meters start low with headroom (no saturation).
            ds.value = Math.max(0, Math.min(100, Math.round((ds.value + valueDelta) * 10) / 10));
            ds.ip = Math.max(0, Math.min(100, Math.round((ds.ip + ipDelta) * 10) / 10));
            ds.ttm = Math.max(4, Math.min(24, ds.ttm + ttmDelta));

            ds.valueHistory.push(Math.round(ds.value));
            ds.ipHistory.push(Math.round(ds.ip));
            ds.ttmHistory.push(ds.ttm);

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            // v1.1.0 fix: persist instructor-card composite to domainState every period.
            if (!ds.performance) ds.performance = {};
            ds.performance.overallScore = this._composite(ds);

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                ip: Math.round(ds.ip),
                ipDelta: Math.round(ipDelta),
                ttm: ds.ttm,
                budgetUsed: ds.budgetUsed,
                overBudget: ds.overBudget,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            const self = this;
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);

            uiManager.bind(`valueDisplay`, `domainState.value`, (v) => {
                const card = document.querySelector(`.opensim-card-value`);
                if (card) {
                    card.classList.toggle(`opensim-value-win`, Number(v) >= self.TARGET_VALUE);
                    card.classList.toggle(`opensim-value-low`, Number(v) < 40);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`ipDisplay`, `domainState.ip`, (v) => {
                const card = document.querySelector(`.opensim-card-ip`);
                if (card) card.classList.toggle(`opensim-ip-weak`, Number(v) < 45);
                return Math.round(Number(v));
            });
            uiManager.bind(`ttmDisplay`, `domainState.ttm`, (v) => {
                const card = document.querySelector(`.opensim-card-ttm`);
                if (card) {
                    card.classList.toggle(`opensim-ttm-window`, Number(v) <= self.WINDOW_TTM);
                    card.classList.toggle(`opensim-ttm-late`, Number(v) > self.WINDOW_TTM + 3);
                }
                return self._fmtMonths(Number(v));
            });
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const card = document.querySelector(`.opensim-card-budget`);
                const cap = self.BUDGET_CAP + (ds ? ds.headroom : 0);
                if (card) card.classList.toggle(`opensim-budget-over`, Number(v) > cap + 0.01);
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(self.BUDGET_CAP);
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const cap = self.BUDGET_CAP + (ds ? ds.headroom : 0);
                const bar = document.querySelector(`.opensim-budget-bar`);
                if (bar) bar.classList.toggle(`opensim-bar-over`, Number(v) > cap + 0.01);
                return self._fmtMoney(Number(v)) + ` / ` + self._fmtMoney(cap);
            });

            // Openness slider readout.
            const op = document.getElementById(`opennessInput`);
            const opReadout = document.getElementById(`opennessReadout`);
            if (op && opReadout) {
                opReadout.textContent = op.value;
                op.addEventListener(`input`, function() { opReadout.textContent = op.value; });
            }

            // Speed slider readout.
            const sp = document.getElementById(`speedInput`);
            const spReadout = document.getElementById(`speedReadout`);
            if (sp && spReadout) {
                spReadout.textContent = sp.value;
                sp.addEventListener(`input`, function() { spReadout.textContent = sp.value; });
            }
        }

        _fmtMoney(v) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const n = Math.round(Number(v) * 10) / 10;
            const num = (Math.abs(n % 1) < 0.05) ? String(Math.round(n)) : n.toFixed(1);
            if (lang === `es`) {
                return num.replace(`.`, `,`) + ` M€`;
            }
            return `€` + num + `M`;
        }

        _fmtMonths(v) {
            const lang = (window.mySimulation && window.mySimulation.language) || `en`;
            const n = Math.round(Number(v));
            return n + (lang === `es` ? ` mes` + (n === 1 ? `` : `es`) : ` mo`);
        }

