        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.valueHistory.map((_, i) => (i === 0 ? this._tt(`chart_start`) : this._tt(`chart_round_prefix`) + i));
            return {
                openChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.valueHistory },
                        { data: ds.ipHistory },
                        { data: ds.ttmHistory }
                    ]
                }
            };
        }

        _composite(ds) {
            const value = Math.round(ds.value);
            const ip = Math.round(ds.ip);
            const ttm = ds.ttm;
            const ttmScore = Math.max(0, Math.min(100, Math.round((this.START_TTM - ttm) / (this.START_TTM - 4) * 100)));
            return Math.round(value * 0.45 + ip * 0.35 + ttmScore * 0.20);
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const ip = Math.round(ds.ip);
            const ttm = ds.ttm;

            const hitTarget = value >= this.TARGET_VALUE;
            const defensible = ip >= 60;
            const inWindow = ttm <= this.WINDOW_TTM;
            const onCap = !ds.overBudget;
            // Composite blends value capture, IP defensibility and a time-to-market score.
            const composite = this._composite(ds);

            let performanceKey = `grade_table`;
            if (hitTarget && defensible && inWindow && onCap && composite >= 72) performanceKey = `grade_mastery`;
            else if (hitTarget && defensible && onCap) performanceKey = `grade_coherent`;
            else if (ds.overBudget) performanceKey = `grade_bust`;
            else if (ds.armedRival) performanceKey = `grade_armed`;
            else if (hitTarget) performanceKey = `grade_nocore`;
            else if (value > this.START_VALUE + 18) performanceKey = `grade_short`;
            const met = hitTarget && defensible && inWindow && onCap && composite >= 72;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && defensible && inWindow && onCap) insights.push(window.mySimulation.t(`insight_mastery`));
            else if (hitTarget && defensible) insights.push(window.mySimulation.t(`insight_coherent`));
            else if (!hitTarget) insights.push(window.mySimulation.t(`insight_short`));

            if (ds.overBudget) insights.push(window.mySimulation.t(`insight_bust`));
            if (ds.armedRival) insights.push(window.mySimulation.t(`insight_armed`));
            if (!ds.licensed) insights.push(window.mySimulation.t(`insight_idle`));
            if (ip < 45) insights.push(window.mySimulation.t(`insight_weakcore`));
            if (!inWindow) insights.push(window.mySimulation.t(`insight_late`));
            if (hitTarget && defensible && inWindow && onCap) insights.push(window.mySimulation.t(`insight_leverage`));

            return {
                value: value,
                ip: ip,
                ttm: ttm,
                hitTarget: hitTarget,
                defensible: defensible,
                inWindow: inWindow,
                composite: composite,
                performance: performance,
                performanceKey: performanceKey,
                met: met,
                overBudget: !!ds.overBudget,
                armedRival: !!ds.armedRival,
                onCap: onCap,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const t = (k, v) => window.mySimulation.t(k, v);
            const s = summary || {};
            const score = (s.composite != null) ? s.composite : 0;
            const grade = s.performance || (s.performanceKey ? t(s.performanceKey) : ``);
            const badges = [];
            badges.push(`<span class="opensim-cm-badge ` + (s.met ? `opensim-cm-met` : `opensim-cm-fail`) + `">` + (s.met ? t(`cm_met`) : t(`cm_not_met`)) + `</span>`);
            if (s.overBudget) badges.push(`<span class="opensim-cm-badge opensim-cm-fail">` + t(`cm_fail_bust`) + `</span>`);
            if (s.armedRival) badges.push(`<span class="opensim-cm-badge opensim-cm-fail">` + t(`cm_fail_armed`) + `</span>`);
            if (s.hitTarget === false || s.defensible === false) badges.push(`<span class="opensim-cm-badge opensim-cm-fail">` + t(`cm_fail_core`) + `</span>`);
            const kpi = (label, val) => `<div class="opensim-cm-metric"><div class="opensim-cm-metric-val">` + val + `</div><div class="opensim-cm-metric-lbl">` + label + `</div></div>`;
            const kpis = kpi(t(`cm_value`), (s.value != null ? s.value : 0)) + kpi(t(`cm_ip`), (s.ip != null ? s.ip : 0)) + kpi(t(`cm_ttm`), (s.ttm != null ? s.ttm : 0));
            const insights = (s.insights || []).map((x) => `<li>` + x + `</li>`).join(``);
            return `<div class="opensim-cm">`
                + `<div class="opensim-cm-head"><div class="opensim-cm-title">` + t(`cm_title`) + `</div>`
                + `<div class="opensim-cm-scorewrap"><span class="opensim-cm-score">` + score + `</span><span class="opensim-cm-score-max">/100</span></div>`
                + `<div class="opensim-cm-grade">` + grade + `</div>`
                + `<div class="opensim-cm-badges">` + badges.join(``) + `</div></div>`
                + `<div class="opensim-cm-metrics">` + kpis + `</div>`
                + `<div class="opensim-cm-insights"><div class="opensim-cm-insights-title">` + t(`cm_insights_title`) + `</div><ul>` + insights + `</ul></div>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overBudget) return window.mySimulation.t(`hint_bust`);
            if (ds.armedRival) return window.mySimulation.t(`hint_armed`);
            if (state.currentPeriod >= 2 && !ds.licensed) return window.mySimulation.t(`hint_idle`);
            if (ds.ip < 40) return window.mySimulation.t(`hint_ip`);
            if (state.currentPeriod >= 3 && ds.value < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.value >= this.TARGET_VALUE && ds.ip >= 60 && ds.ttm <= this.WINDOW_TTM) return window.mySimulation.t(`hint_strong`);
            return null;
        }

